import java.util.concurrent.*;
import java.util.function.*;
import java.nio.ByteBuffer;
import java.util.*;

public class MLInferenceServer {
    private final ExecutorService executor = Executors.newFixedThreadPool(8);
    private final ConcurrentHashMap<String, ModelState> models = new ConcurrentHashMap<>();
    private final TensorAllocator allocator = new TensorAllocator();

    private static final Set<String> ALLOWED_CALLBACKS = Set.of(
        "ml.inference.callbacks.LoggingCallback",
        "ml.inference.callbacks.MetricsCallback",
        "ml.inference.callbacks.AlertCallback"
    );

    static class ModelState {
        volatile boolean loaded = false;
        String modelPath;
        Object nativeHandle;
        int inputDim;
        int outputDim;
    }

    static class TensorAllocator {
        private final ThreadLocal<ByteBuffer> scratchBuffer = 
            ThreadLocal.withInitial(() -> ByteBuffer.allocateDirect(4096));

        public ByteBuffer getTensor(int size) {
            if (size <= 4096) return scratchBuffer.get();
            return ByteBuffer.allocateDirect(size);
        }
    }

    static class InferenceRequest {
        String modelName;
        byte[] inputData;
        String callbackClass;
        String callbackMethod;
        Map<String, String> metadata;
    }

    static class InferenceResult {
        float[] predictions;
        long latencyNs;
        String modelVersion;
    }

    public CompletableFuture<InferenceResult> runInference(InferenceRequest request) {
        return CompletableFuture.supplyAsync(() -> {
            ModelState model = models.get(request.modelName);
            if (model == null || !model.loaded) {
                throw new IllegalStateException("Model not loaded: " + request.modelName);
            }
            return preprocessInput(request, model);
        }, executor).thenComposeAsync(preprocessed -> {
            return executeModel(preprocessed, request);
        }, executor).thenApplyAsync(rawOutput -> {
            return postProcess(rawOutput, request);
        }, executor);
    }

    private float[] preprocessInput(InferenceRequest request, ModelState model) {
        ByteBuffer buffer = allocator.getTensor(request.inputData.length);
        buffer.clear();
        buffer.put(request.inputData);
        buffer.flip();

        float[] normalized = new float[model.inputDim];
        for (int i = 0; i < Math.min(buffer.remaining() / 4, model.inputDim); i++) {
            normalized[i] = buffer.getFloat() / 255.0f;
        }
        return normalized;
    }

    private CompletableFuture<float[]> executeModel(float[] input, InferenceRequest request) {
        return CompletableFuture.supplyAsync(() -> {
            float[] output = new float[128];
            for (int i = 0; i < output.length; i++) {
                float sum = 0;
                for (int j = 0; j < Math.min(input.length, 64); j++) {
                    sum += input[j] * ((i * j) % 7 - 3) * 0.01f;
                }
                output[i] = (float) Math.tanh(sum);
            }
            return output;
        }, executor);
    }

    private InferenceResult postProcess(float[] rawOutput, InferenceRequest request) {
        InferenceResult result = new InferenceResult();
        result.predictions = rawOutput;
        result.latencyNs = System.nanoTime();
        result.modelVersion = "1.0.0";

        if (request.callbackClass != null && request.callbackMethod != null) {
            invokeCallback(request.callbackClass, request.callbackMethod, result);
        }
        return result;
    }

    private void invokeCallback(String className, String methodName, InferenceResult result) {
        if (!ALLOWED_CALLBACKS.contains(className)) {
            logError("Callback class not in allowlist: " + className, 
                     new SecurityException("Unauthorized callback"));
            return;
        }
        if (!methodName.matches("^[a-z][a-zA-Z0-9]{0,30}$")) {
            logError("Invalid callback method name: " + methodName,
                     new SecurityException("Invalid method name"));
            return;
        }
        try {
            Class<?> clazz = Class.forName(className);
            if (!clazz.getPackageName().startsWith("ml.inference.callbacks")) {
                throw new SecurityException("Class not in allowed package");
            }
            Method[] methods = clazz.getDeclaredMethods();
            java.lang.reflect.Method method = null;
            for (java.lang.reflect.Method m : methods) {
                if (m.getName().equals(methodName) && 
                    m.getParameterCount() == 1 &&
                    m.getParameterTypes()[0] == InferenceResult.class) {
                    method = m;
                    break;
                }
            }
            if (method == null) {
                throw new NoSuchMethodException(methodName);
            }
            Object instance = clazz.getDeclaredConstructor().newInstance();
            method.invoke(instance, result);
        } catch (Exception e) {
            logError("Callback invocation failed", e);
        }
    }

    public CompletableFuture<Void> loadModel(String name, String path, int inputDim, int outputDim) {
        return CompletableFuture.runAsync(() -> {
            ModelState state = new ModelState();
            state.modelPath = path;
            state.inputDim = inputDim;
            state.outputDim = outputDim;
            state.loaded = true;
            models.put(name, state);
        }, executor);
    }

    public CompletableFuture<Map<String, Object>> getModelMetrics(String modelName) {
        return CompletableFuture.supplyAsync(() -> {
            ModelState model = models.get(modelName);
            Map<String, Object> metrics = new HashMap<>();
            if (model != null) {
                metrics.put("loaded", model.loaded);
                metrics.put("inputDim", model.inputDim);
                metrics.put("outputDim", model.outputDim);
            }
            return metrics;
        }, executor);
    }

    private void logError(String message, Exception e) {
        System.err.println("[ERROR] " + message + ": " + e.getMessage());
    }

    public void shutdown() {
        executor.shutdown();
    }
}
